from pathlib import Path
import json,pandas as pd,numpy as np
root=Path(__file__).parent/'current_report';out=root/'comparison';s=json.loads((out/'summary.json').read_text());v=json.loads((root/'report_data.json').read_text())['summary'];m=pd.read_csv(out/'galaxy_by_galaxy_comparison.csv',dtype={'object_id':str});common=m.codex_fit_status.eq('provisional_fit')&m.status.eq('ok')
review=m.loc[common&((m.disc_PA_delta_deg.abs()>20)|(m.bar_PA_delta_deg.abs()>20)|(m.inclination_delta_deg.abs()>20))].copy();review['max_PA_absolute_difference_deg']=review[['disc_PA_delta_deg','bar_PA_delta_deg']].abs().max(axis=1);review.sort_values('max_PA_absolute_difference_deg',ascending=False).to_csv(out/'large_differences_for_review.csv',index=False)
lines=['# Current adaptive MER VIS geometry compared with supplied method','','20 October 2026','','This comparison uses the completed adaptive v2 run and replaces the comparison against the original fixed-centre run. All2777 object IDs, FITS filenames and coordinates match. Neither source is modified by the comparison.','',f"Current pipeline: {v['fits']} disc measurements and {v['failures']} failures. Supplied method: 2776 ok rows and one failure. The current pipeline recovers {v['recovered_original_failures']} of the original570 failed cases. Missing bar measurements are excluded from bar comparisons, not replaced with zeros.",'','| Subset | Disc PA median absolute difference | Bar PA median absolute difference | Inclination median absolute difference |','|---|---:|---:|---:|']
for name,key in [('All common measurements','common'),('Current pipeline with no counted flags','codex_revised_unflagged'),('Neither table has counted flags','both_unflagged')]:
 z=s['statistics'][key];lines.append('| '+name+' | '+' | '.join(f"{z[c]['median_abs']:.2f}° (n={z[c]['n']})" if z[c]['n'] else 'Unavailable' for c in ['disc_PA_delta_deg','bar_PA_delta_deg','inclination_delta_deg'])+' |')
lines+=['','Differences are current Codex minus supplied; axial PA differences wrap into[-90,90). These are consistency comparisons, not independent accuracy measurements. Both pipelines use the same underlying images and Photutils.','', 'Both methods explicitly use observed sky PA from North towards East modulo180. No additional90° correction is applied to the supplied fitted PAs. The adopted extra90° applies only to the Euclid detection-catalogue comparison.','', 'Inclination assumptions differ: current Codex retains a circular thin disc(q0=0); the supplied methodology specifies q0=0.2. Thus differences include intrinsic-thickness assumptions as well as fitted disc shape.','', 'The updated pipeline uses adaptive binning and intervals, fits and checks galaxy centres, retains disc-only results when no bar passes, and labels relaxed, iteration-limited and mask/interval recovery. The supplied method also uses adaptive fitting but has different weighting, acceptance and recovery rules. Its stop-code2 description should be corrected: Photutils defines this as iteration-limit exceeded, not normal convergence. Current code admits selected code2 samples only in explicitly relaxed recovery.','', f'{len(review)} common-fit objects differ by more than20° in at least one available quantity. See large_differences_for_review.csv. Face-on disc PA disagreement is often an orientation ambiguity rather than an impediment to deprojection.','', 'The full joined CSV preserves original values, flags, methods and ranges alongside the signed differences. summary.json retains file checksums and more detailed subsets. Current report summaries and QI groups must not be interpreted using the original flags or earlier failure counts.']
lines+=['','## Before and after on exactly the same galaxies','','These subsets require available old, current and supplied measurements. A bar must be accepted in the new run, so the bar subset is selective. Agreement is not independent accuracy.','', '| Quantity | Matched galaxies | Original median absolute difference | Current median absolute difference |','|---|---:|---:|---:|']
for k,z in v['paired_supplied_comparison'].items():
 if z['n']:lines.append(f"| {k} | {z['n']} | {z['before_median_abs']:.2f}° | {z['after_median_abs']:.2f}° |")

(out/'comparison_summary.md').write_text('\n'.join(lines),encoding='utf8');print('Current comparison written')
